public class InsufficientAccountBalanceException extends RuntimeException {
    private final String accountNumber;
    private final double attemptedDebit;

    public InsufficientAccountBalanceException(String accountNumber, double attemptedDebit) {
        super(String.format("Account %s lacks funds for debit of %.2f", accountNumber, attemptedDebit));
        this.accountNumber = accountNumber;
        this.attemptedDebit = attemptedDebit;
    }

    public String getAccountNumber() {
        return accountNumber;
    }

    public double getAttemptedDebit() {
        return attemptedDebit;
    }
}
